    uploadComposerTools: 'সরাসরি কম্পোজারে ছবি বা ভিডিও পেস্ট করুন, পুরো পোস্টটি ড্রাফট হিসেবে সেভ করুন, পরবর্তীতে পোস্ট করার জন্য শিডিউল করুন (শিডিউল করা পোস্ট আপনার প্রোফাইলে দেখা যাবে), এটিকে "বাচ্চাদের জন্য তৈরি" বা ম্যাচিউর হিসেবে মার্ক করুন এবং একই ধাপে আপনার অন্যান্য সোশ্যাল অ্যাকাউন্টে পাঠিয়ে দিন। ভিডিওর কভার পরবর্তীতে \'এডিট পোস্ট\' থেকে পরিবর্তন করা যাবে।',
    labelScheduleLive: 'স্টেজ বা স্ট্রিম শিডিউল করুন:',
    uploadScheduleLive: 'স্টেজ এবং লাইভস্ট্রিমগুলো একই কম্পোজার থেকে শিডিউল করা যায় যেখান থেকে আপনি পোস্ট করেন, তাই ঘোষণা, শেয়ার কার্ড এবং রিমাইন্ডারগুলো এক ধাপেই সেটআপ হয়ে যায়।',
    tocAllowance: 'পোস্টিং অ্যালাউন্স',
    allowanceTitle: 'দৈনিক পোস্টিং অ্যালাউন্স',
    allowanceIntro: 'DeHub-এ প্রতিদিন পোস্টিং ফ্রি, তবে তা আপনার স্টেকিং ব্যাজের সাথে সামঞ্জস্যপূর্ণ একটি লিমিট পর্যন্ত। সবাই প্রতিদিন দশটি টেক্সট পোস্ট এবং এক গিগাবাইট ভিডিও, ছবি ও অডিও আপলোড করার সুযোগ পায়। এর বেশি কিছু করলে সেই দিনের বাকি অংশ DeHub টোকেনে পরিশোধ করতে হবে — প্রতি টেক্সট পোস্ট ১০ সেন্ট, প্রতি গিগাবাইট ২ ডলার, যা শুধুমাত্র অতিরিক্ত অংশের জন্য চার্জ করা হয়।',
    allowanceIntro2: 'টেক্সট পোস্ট এবং মিডিয়া আলাদা পুল। একটি শেষ হয়ে গেলে অন্যটিতে কোনো প্রভাব পড়ে না, তাই ভিডিও আপলোড করে লিমিট শেষ হয়ে গেলেও দশটি টেক্সট পোস্ট ফ্রি থাকে। উভয়ই প্রতিদিন মধ্যরাত UTC-তে রিসেট হয়।',
    allowanceHowTitle: 'পেমেন্ট যেভাবে কাজ করে',
    allowanceHowDesc: 'অর্ডারটি গুরুত্বপূর্ণ এবং এটি ইচ্ছাকৃতভাবেই করা হয়েছে: কোনো পোস্ট পাবলিশ না হলে আপনাকে কখনোই চার্জ করা হবে না, এবং বড় কোনো ফাইল আপলোড করার পর আপনাকে বলা হবে না যে আপনি সেটির জন্য পেমেন্ট করতে পারবেন না।',
    allowanceStep1Title: 'আপলোডের আগে',
    allowanceStep1: 'অ্যাপটি আজকের দিনের আপনার আগের পোস্টগুলোর সাথে দাম চেক করে এবং নিশ্চিত করে যে আপনার ওয়ালেটে পর্যাপ্ত ব্যালেন্স আছে। পেমেন্ট নিশ্চিত না হওয়া পর্যন্ত কোনো চার্জ কাটা হয় না এবং কোনো কিছু আপলোড হয় না।',
    allowanceStep2Title: 'পোস্ট পাবলিশ হওয়া',
    allowanceStep2: 'আপনার পোস্টটি ঠিক সেভাবেই লাইভ হয় যেভাবে ফ্রি অ্যালাউন্সের ভেতরে হতো। পাবলিশ হওয়ার জন্য পেমেন্টের অপেক্ষায় থাকতে হয় না।',
    allowanceStep3Title: 'তারপর আপনি পেমেন্ট করেন',
    allowanceStep3: 'শুধুমাত্র সেই পোস্টের জন্য একটি ট্রান্সফার, একটি সিগনেচার। এটি Base বা BNB চেইন, যার মধ্যে পর্যাপ্ত DeHub টোকেন আছে, তাতেই সেটেল হয়ে যায়।',
    allowanceUnpaidTitle: 'যদি আপনি প্রত্যাখ্যান করেন',
    allowanceUnpaidDesc: 'পোস্টটি পাবলিশই থাকবে। বকেয়া পরিমাণটি আপনার অ্যাকাউন্টে ওপেন থাকবে এবং পরবর্তী পেইড পোস্ট করা থেকে আপনাকে ব্লক করবে যতক্ষণ না তা পরিশোধ করা হয় — তবে ফ্রি পোস্টের ক্ষেত্রে কোনো বাধা নেই। আগামীকালের অ্যালাউন্স থেকে আপনি যা পাবেন তা সবসময়ই আপনার, বকেয়া থাকুক বা না থাকুক।',
    allowanceCountsTitle: 'অইটার বিপরীতে কিতা গন্য অয়',
    allowanceCounts1: 'টেক্সট-অনলি পোস্টগুলা আপনার প্রতিদিনের টেক্সট পোস্টের কোটা থিকা একটা কইরা খরচ করে।',
    allowanceBadgeNote: 'একটা ব্যাজ একসাথে দুইটা অংশই বাড়ায় — একটা বড় ফ্রি অ্যালাউন্স আর তার পরের সবকিছুর দাম কমায়। এই ডিসকাউন্টটা সেইম, যেটা ল্যাডার ব্যাজ হোল্ডাররা ডিহাব (DeHub) টোকেন কেনার সময় অলরেডি পায়, ক্র্যাব (Crab)-এ ৫% থিকা মেগালোডন (Megalodon)-এ ৩০% পর্যন্ত, তাই একটা ব্যাজের দাম কত অইটার উত্তর একটাই। আপনার অ্যালাউন্সটা আসে আপনার নিজের কামাই করা ব্যাজ থিকা: কোনো প্যাট্রনের দেওয়া টিয়ার আপনার প্রোফাইলে দেখা গেলেও, অইটা আপনাকে তাদের পোস্টিং অ্যালাউন্স দেয় না।',
