    futureTitle: 'কন্টেন্ট ইকোনমিক্সের ভবিষ্যৎ',
    futureDesc: 'DeHub-এর ERC-1155 ফ্র্যাকশনাইজড কন্টেন্ট মডেলটি অস্থায়ী ক্রিয়েটর-ফ্যান সম্পর্কের থেকে স্থায়ী অর্থনৈতিক অংশীদারিত্বের বিবর্তনকে তুলে ধরে। ক্রিয়েটরদের যেকোনো আপলোডকে ১,০০০টি ট্রেডযোগ্য ফ্র্যাকশনে মিন্ট করার সুযোগ দিয়ে, আমরা এমন প্রথম প্ল্যাটফর্ম তৈরি করছি যেখানে কন্টেন্টের সাফল্য সরাসরি এবং স্থায়ীভাবে এর সাথে জড়িত সবাইকে—ক্রিয়েটর, ফ্যান এবং বিনিয়োগকারী—চিরকালের জন্য উপকৃত করে, কোনো চলমান প্রচেষ্টা বা প্ল্যাটফর্মের উপর নির্ভরশীলতা ছাড়াই।',
