    topUpDesc: 'আমরার নিজস্ব ইন-অ্যাপ কারেন্সি আছে, যেমন ফোর্টনাইট-এর ভি-বাক্স (Vbucks) বা টিকটক কয়েন, আমরার এগুলারে কয় DeHub টোকেন। অ্যাপের সব জায়গায় আপনে এগুলারে সোনালী কয়েন হিসেবে দেখবা। এগুলা প্রিমিয়াম সার্ভিস যেমন টিপস, সাবস্ক্রিপশন আর আরও অনেক কিছুর লাগি ব্যবহার করা হয়। ব্রাউজিং ফ্রি, আর প্রত্যেক অ্যাকাউন্টের ডেইলি অ্যালাউন্সের ভিতরে পোস্ট করাও ফ্রি — যদি আপনে সোশ্যাল মিডিয়া, ইমেইল বা এসএমএস দিয়া সাইন আপ করেন, তাইলে আমরা আপনার সব গ্যাস ফি স্পন্সর করি। ওয়ালেট ব্যবহারকারীরা স্ট্যান্ডার্ড ETH বা BNB গ্যাস ফি দেন। নিচে ২ ক্লিকে টোকেন টপ আপ করইন।',
    directTitle: 'ডাইরেক্ট',
