    badgeUnlock5: 'আপনার কাজের বেশি গুরুত্ব: ব্যাজ হোল্ডারের একটা ভিউ বা রিঅ্যাকশন বেশি কাউন্ট হয়, গভর্ন্যান্স ভোটিংয়ের মতো — ব্যাজ ছাড়া ১, ক্র্যাবে ২, আর মেগালোডন পর্যন্ত প্রতি টায়ারে একটা কইরা বাড়ে, সর্বোচ্চ ১৪ পর্যন্ত। এটা আপনার একটা রিঅ্যাকশনের মাল্টিপ্লায়ার, দুইটা রিঅ্যাকশন না।',
