    privateByDesignDesc: 'DeHub শুধু এনক্রিপ্টেড মেসেজের সাইফারটেক্সট স্টোর করে। আপনার কি (key) আপনার ডিভাইসের একটা ওয়ালেট সিগনেচার থাকি তৈরি হয় আর তা কখনো আমাদের কাছে পাঠানো হয় না।',
