    spNameSecondWind: 'সেকেন্ড উইন্ড (Second Wind)',
    spDescSecondWind: 'এক সপ্তাহের বেশি পুরানা একটা পোস্টরে আবার ফিডের উপরে পাঠান।',
    spDescCommentAnchor: 'অন্য কারো কমেন্ট থ্রেডের উপরে ধরিয়া রাখা। লেখকের নিজের পোস্টে থাকা ফ্রি পিনের মতো না — এইটা আপনার, অন্যর থ্রেডে, আর এইটার মেয়াদ শেষ হইয়া যায়।',
    spDescTrendJacker: 'আপনার ক্যাটাগরির একটাকে ট্রেন্ডিং লিস্টে রাখা, যেখানে পুরা প্ল্যাটফর্মের নজর আছে।',
    spDescTimelineBomber: 'আপনার ফলোয়াররা অন্য কারো বুস্টের আগে আপনার পোস্ট দেখবো, তাইলে যারা আপনার কথা হুনতে চায়, তাদের কাছে একটা কিং কোবরা মেগালোডনের লগে লড়াইয়ে জিতবো।',
    spDescSignalFlare: 'আপনার ফলোয়ারদের কাছে একটা পোস্ট নিয়া একটা নোটিফিকেশন। এইটা আলাদা সিগন্যাল অ্যালাউন্স থিকা খরচ হয়, আপনার বুস্ট থিকা না।',
    spDescFlakJacket: 'এইটা চলাকালীন আপনার পোস্ট ডাউনভোট দিয়া নিচে নামানি যাইবো না — এইটা পাইল-অন থিকা সুরক্ষা, দ্বিমত থিকা না।',
    spDescPrecisionStrike: 'আপনি যে অ্যাকাউন্টের নাম কইবেন, তাদের ফলোয়ারদের কাছে পৌঁছান, তারা আপনাকে ফলো করুক বা না করুক।',
    spDescHarpoon: 'আপনার পছন্দ করা ব্যাজ টায়ারের প্রত্যেক হোল্ডারকে একটা পোস্ট নিয়া নোটিফাই করা। এইটাও সিগন্যাল অ্যালাউন্স থিকা দেওয়া হয়।',
    spDescTeamUp: 'সাতটা পর্যন্ত অন্য অ্যাকাউন্টের লগে ওয়ালেট পাওয়ার যোগ করা। টিমের সবাই সেই ব্যাজটা পায় যেটা পুল করা ব্যালেন্স দিয়া আনলক হয়, আর এইটার জন্য কিছু খরচ করা লাগে না। টিম প্রাইভেট হইতে পারে, যাতে মানুষ জয়েন করার জন্য রিকোয়েস্ট দেয় আর ওনার তা অ্যাপ্রুভ করে।',
    spDescFrontRow: 'আপনার লাইভ স্টেজ চলাকালীন স্টেজ রেইলের সবার উপরে থাকবো, সব সারফেসের স্টেজ লিস্টে।',
    spDescDeepCurrent: 'আপনার একটা বুস্ট অন্য কারো পোস্টে দেওয়া। টপ রাং হইলো সেইটা যেটা অন্য মানুষের জন্য আপনার রিচ খরচ করে।',
    spLadderTitle: 'প্রতিটা ব্যাজ যা দেয়',
    spLadderDesc: 'পাক্ষিক বুস্ট, আর প্রতিটা কতক্ষণ চলে। আপনি উপরে উঠলে কোনো কলামই নিচে নামে না, আর টোটাল সবসময় বাড়ে।',
    spColUnlocks: 'আনলকস',
    spMinShort: 'মিনিট',
    spNoAllowance: 'কোনো অ্যালাউন্স নাই',
    spQuantityOnly: 'বেশি রিচ, নতুন কোনো পাওয়ার নাই',
    spRotationTitle: 'স্লট যেভাবে শেয়ার করা হয়',
    spRotationDesc: 'স্লট পিন না হইয়া রোটেট করে। যখন একসাথে অনেকগুলা বুস্ট চলে, তখন প্রত্যেক ভিউয়ারকে একটা কইরা দেখানো হয়, বুস্টারের ব্যাজ টায়ার অনুযায়ী — হাই টায়ার বেশিবার দেখানো হয়, আর সবাই তাদের কেনা সময়টা পায়। বুস্ট দিয়া যা কেনা হয় তা হইলো নির্দিষ্ট মিনিটের জন্য ভয়েসের শেয়ার, ফিডের একদম উপরে একচ্ছত্র দখল না।',
    spCycleDesc: 'এই সাইকেলটা পুরা প্ল্যাটফর্মের জন্য চৌদ্দ দিনের, তাই সবার অ্যালাউন্স একই সময়ে রিফিল হয়। কিছুই পরের সাইকেলে যায় না। শুরু হওয়ার আগে বুকিং ক্যানসেল করলে মিনিটগুলা সেই সাইকেলেই ফেরত যায় যেখান থিকা আপনি পে করছিলেন।',
    spSafetyTitle: 'বুস্ট যা করতে পারে না',
    spSafetyDesc: 'প্রতিটা ড্র সেই মুহূর্তে পোস্টের অবস্থা অনুযায়ী চেক করা হয়, তাই যে পোস্ট রিমুভ, ব্লক বা ম্যাচিউর মার্ক করা হইছে তা কোনো অপরিচিত মানুষের ফিডে যাইবো না। ম্যাচিউর পোস্ট বুকিংয়ের সময়ও রিফিউজ করা হয়, আর যে আপনাকে বা আপনি যাকে বুস্ট করছেন তাকে ব্লক করছে, তার কাছে বুস্ট কখনোই যাইবো না।',
