    feeTierDesc: 'আমাদের বিপ্লবী ফি গঠন ডিহাব টোকেন মালিকদের সাথে গুরুত্বপূর্ণভাবে হ্রাস করা প্ল্যাটফর্ম ফি পুরস্কার করে। শুরু করার জন্য 10% মানদণ্ডী ফি, প্রতিটি বেডজ তীর অর্জন করে টোকেন মালিকানার সাথে ফি হ্রাস করে 0.69%, অবশেষে শুধুমাত্র 1% মেগালোডন বেডজ মালিকদের জন্য - আমাদের সবচেয়ে অঙ্গীকৃত সম্প্রদায় সদস্যদের জন্য 99% ফি হ্রাস।',
