    feeDisclaimerDesc: 'ফি শুধুমাত্র কিছু সেবা যেমন টিপ, সাবস্ক্রিপশন, পে-পার-ভিউ এবং ওয়াচ2ইয়ার বাউন্টি প্রয়োগ করে। ব্যবহারকারীরা অ্যাপের মাধ্যমে অন্য ব্যবহারকারীদের টোকেন পাঠাতে পারে এবং আমাদের অ্যাবস্ট্রাকশন টুলগুলি ব্যবহার করে এটি করতে পারে কোনো ওয়ালেট অ্যাড্রেস বা প্রাইভেট কী পরিচালনা করার প্রয়োজন নেই।',
