    tocStudio: 'ক্রিয়েটর স্টুডিও',
    tocSettings: 'সেটিংস',
    tocMore: 'অ্যাপের আরও কিছু',
    feedsTitle: 'ফিড ও কন্টেন্ট ফরম্যাট',
    feedsDesc: 'ডি-হাব (DeHub)-এর হোম সারফেস হইলো একটা সিঙ্গেল ট্যাবড ফিড, যেটার মইধ্যে সব ধরনের কন্টেন্ট ফরম্যাট একসাথে থাকে। ক্রিয়েটরদের একটা নির্দিষ্ট মিডিয়ামে বাধ্য না কইরা, এই ফিডটা টেক্সট, ইমেজ, লং-ফর্ম ভিডিও, শর্ট-ফর্ম রিলস, মিউজিক আর লাইভ স্ট্রিমরে এক স্ক্রলে মিলাইয়া দেয়, আর ভিউয়াররা যখন ইচ্ছা তখন একটা নির্দিষ্ট ফরম্যাটে ফিল্টার করতে পারে। ফরম্যাট যাই হোক, প্রত্যেকটা কার্ডের মইধ্যে একই সোশ্যাল আর মনিটাইজেশন কন্ট্রোল থাকে: লাইক, কমেন্ট, রিপোস্ট, কোট, বুকমার্ক আর ডি-হাব টোকেনে টিপ দেওয়া।',
    feedsDesc2: 'ফিডের উপরের দিকে ট্যাব হিসেবে ফরম্যাটগুলা থাকে। ডিফল্ট হোম ট্যাবে আপনি যাদের ফলো করেন তাদের সব কিছু একসাথে দেখা যায়; আর ডেডিকেটেড ট্যাবগুলা দিয়া আপনি চাইলে শুধু একটা মিডিয়াম দেখতে পারেন, যেমন শুধু লং-ফর্ম ভিডিও বা শুধু মিউজিক। র‍্যাঙ্কিং হইলো এই পেজের নিচে দেওয়া প্ল্যাটফর্ম লিডারবোর্ড অ্যালগরিদম অনুযায়ী, তাই বিজ্ঞাপনের টাকার বদলে কোয়ালিটি আর এনগেজমেন্টই ঠিক করে কার পোস্ট কত মানুষের কাছে পৌঁছাইবো।',
    feedsHomeDesc: 'টেক্সট, ইমেজ, আর্টিকেল, ভিডিও, অডিও আর লাইভ পোস্টের একটা মিশ্র ফিড। লাইক, কমেন্ট, রিপোস্ট, কোট, বুকমার্ক আর টোকেন টিপিং সব কার্ডের মইধ্যেই আছে, আর পোস্টগুলা গেটেড, পে-পার-ভিউ বা ওয়াচ-টু-আর্ন হিসেবে সেট করা যায়। কেউ যাতে ফিড ফ্লাড করতে না পারে, সেইজন্য হোম ফিডে প্রত্যেক অথরের প্রতিদিন একটা নির্দিষ্ট সংখ্যক পোস্টই দেখা যায়: ব্যাজ ছাড়া একটা, আর প্রত্যেক ব্যাজ টায়ারের জন্য একটা কইরা বেশি, মেগালোডন পর্যন্ত মোট চৌদ্দটা। বাকি সব পোস্ট অথরের প্রোফাইলে আর ফলোয়িং সর্টে দেখা যাইবো।',
    feedsSort: 'সর্টিং ও ফিল্টারিং:',
    feedsSortDesc: 'সর্ট ট্যাবে লেটেস্টগুলা সবার আগে থাকে, তারপরে আসে এনগেজমেন্ট সর্ট, যার মইধ্যে মোস্ট টিপসও আছে। কোনো হ্যাশট্যাগে ট্যাপ করলে ফিড ওইটা অনুযায়ী ফিল্টার হইয়া যায়, যে ভিডিওগুলা আপনি অলরেডি দেখছেন সেগুলা মার্ক কইরা হাইড করা যায়, আর যেকোনো লাইভ স্টেজ হোমের একদম উপরে থাকে।',
    feedsShortsDesc: 'টিকটক-স্টাইল দেখার জন্য একটা ভার্টিক্যাল, সোয়াইপ করা যায় এমন শর্ট-ভিডিও রিল। ডিরেকশন-লকড সোয়াইপ জেস্টার দিয়া ক্লিপের মইধ্যে যাওয়া যায়, মোমেন্টাম ক্যাপ করা থাকে যাতে আপনি একসাথে দুইটা স্কিপ না করেন, আর প্রত্যেক ক্লিপেই মনিটাইজেশন অ্যাপ্লাই হয়।',
    feedsPollsDesc: 'পোল পোস্ট তৈরি করেন আর ফিডের মইধ্যেই ভোট কালেক্ট করেন। পোল খোলা থাকা অবস্থায় রেজাল্ট লাইভ আপডেট হয়, আর সময় শেষ হওয়ার পর সব ভিউয়ার ফাইনাল রেজাল্ট দেখতে পারে: বার, পার্সেন্টেজ আর টোটাল, সাথে বিজয়ী অপশনটা টিক দেওয়া থাকে আর কোনো ভোট বাটন থাকে না।',
    feedsTabs: 'ডেডিকেটেড ট্যাব:',
    feedsTabsDesc: 'ভিডিও, ইমেজ, মিউজিক আর লাইভ ট্যাবের মইধ্যে সুইচ কইরা একবারে একটা ফরম্যাট ব্রাউজ করতে পারেন, যেটার লেআউট ওই মিডিয়ামের জন্য আলাদাভাবে সেট করা।',
    feedsBookmarks: 'বুকমার্ক ও লিডারবোর্ড:',
