    workDesc2: 'যেহেতু এটা নেটিভ, বাউন্টি হান্টিং পুরো ইকোসিস্টেমের লাইগা একটা গ্রোথ ইঞ্জিন হিসেবে কাজ করে। ক্রিয়েটররা এটা ইউজ করে এনগেজমেন্ট বাড়াইতে আর তাদের কমিউনিটি বড় করতে, শেয়ার, ক্লিপ, রিঅ্যাকশন বা কন্টেন্ট ছড়ানোর লাইগা বাউন্টি পোস্ট কইরা। প্রজেক্ট আর বড় DeHub কমিউনিটি এটা ইউজ করে নিজেদের প্রমোট করতে আর ইকোসিস্টেম বড় করতে, হান্টারদের এমন সব কাজের লাইগা রিওয়ার্ড দিয়া যা নতুন মানুষরে প্ল্যাটফর্মে আনে। যে সিস্টেম দিয়া একটা কন্ট্রাক্ট সেটেল হয়, সেই একই সিস্টেম দিয়া একটা কমিউনিটি এনগেজমেন্ট টাস্কও সেটেল হয়।',
    workB1: 'বাউন্টি পোস্ট করইন:',
