    storesTitle: 'স্টোর',
    storesDesc: 'স্টোর দিয়া ক্রিয়েটর আর বিজনেসগুলা DeHub-এর ভেতরেই নিজের দোকান খুলতে পারইন আর সরাসরি অডিয়েন্সের কাছে DeHub টোকেনে বেচাকেনা করতে পারইন। একটা স্টোর তার নিজের পেজে থাকে, ক্রিয়েটরের কন্টেন্টের লগে থাকে, আর ফলোয়াররে কাস্টমারে রূপান্তর করে, কোনো এক্সটারনাল চেকআউটে না নিয়া। যেহেতু পেমেন্ট অ্যাপের বিল্ট-ইন ওয়ালেট দিয়াই হয়, তাই বায়াররা দুই-এক ট্যাপেই কিনতে পারইন আর সেলাররা সরাসরি তাদের ব্যালেন্সে টোকেন পাইয়া যান।',
    storesB1: 'স্টোর খুলইন:',
