    storesB4Desc: 'আপনার স্টোরে প্রিন্ট-অন-ডিমান্ড মার্চেন্ডাইজ লিস্ট করইন, আর পোস্টের লগে স্টোর লিস্টিং বা অ্যাফিলিয়েট লিংক যোগ করইন, যা ওই পোস্টের শপ বোর্ডে দেখা যাইবো।',
    affiliateTitle: 'অ্যাফিলিয়েট আর রেফারেল',
