    affiliateB1Desc: 'প্রতিটা অ্যাকাউন্টের একটা ইউনিক রেফারেল লিংক আর কোড আছে যা আপনি যেকোনো জায়গায় শেয়ার করতে পারইন, এমনকি শর্ট /r/ লিংকও। একটা রেফারেল লিংক DeHub-এর যেকোনো পেজে পয়েন্ট করতে পারে, একটা ইনভাইট পেজ বিভিন্ন ডেস্টিনেশনে নিতে পারে, আর আপনি যে ব্লগ আর্টিকেল শেয়ার করইন সেগুলাতে অটোমেটিক আপনার লিংক থাইকব।',
