    intro1: 'গেমার এবং স্ট্রিমারদের একটি দল হিসেবে, আমরা বেশ কিছু মজার, ফ্রি আর্কেড গেম তৈরি ও রিলিজ করেছি এবং আমাদের প্রথম ফ্ল্যাগশিপ গেম \'লাস্ট চ্যাড স্ট্যান্ডিং\' (Last Chad Standing)-এর কাজ করছি। এটি প্রথম এমএমএ (MMA) ব্যাটল রয়্যাল গেম, যেখানে ইউবিসফট (Ubisoft)-এর মতো প্রতিষ্ঠানের ডেভেলপাররা কাজ করছেন। আমাদের প্রতিষ্ঠাতা টিমের সাথে ইউএফসি (UFC), অক্টাগন (Oktagon) এবং পিএফএল (PFL)-এর তারকাদের গভীর সম্পৃক্ততা রয়েছে। আমরা হোর্হে মাসভিদালের মতো চ্যাম্পিয়নদের নিয়ে ডকুমেন্টারি তৈরি করেছি এবং কনর ম্যাকগ্রেগরের কোচ কাভানার অধীনে প্রশিক্ষণ নিয়েছি। এই ডকুমেন্টারিগুলো ডিহাব (DeHub)-এর পক্ষ থেকে অ্যান্ড্রু টেটের ওয়ার রুমের প্রধান এবং প্রাক্তন ইউএফসি ফাইটার লুক বার্নেট দ্বারা চিত্রায়িত হয়েছিল।',
