    intro3: 'এর আরেকটি বাড়তি সুবিধা হলো, এটি টিম এবং কমিউনিটিকে সাধারণ লক্ষ্য অর্জনের জন্য কঠোর পরিশ্রম করতে উৎসাহিত করে। কারণ আমাদের যত বেশি ইউজার থাকবে, আমরা তত বেশি আয় করব, তত বেশি রিওয়ার্ড তৈরি হবে এবং আমরা আরও বেশি ইউজারকে আকর্ষণ করতে পারব।',
