    chessDesc: 'সিনেমাটিক থ্রিডি চেস, যেখানে প্রতিটি গুটির পেছনে একটি সেনাবাহিনী থাকে। তিনটি সজ্জিত সভ্যতা মার্বেল বোর্ডের ওপর চারটি যুদ্ধক্ষেত্রে মার্চ করে, আক্রমণ করে এবং পড়ে যায়। এতে তিনটি ইঞ্জিন স্ট্রেংথ রয়েছে এবং ইলো (Elo) রেটিংয়ের ভিত্তিতে অনলাইন ল্যাডার সিস্টেম আছে।',
