    disclaimerText: 'DeHub টোকেনগুলো কঠোরভাবে ইউটিলিটি পারপাসের জন্য, ঠিক যেমন যেকোনো ইন-গেম বা ইন-অ্যাপ ডিজিটাল টোকেন বা কারেন্সি, এগুলো কোনোভাবেই ইনভেস্টমেন্ট নয়। যেহেতু আমাদের টোকেন অন-চেইন থাকে, তাই আমরা বাড়তি ইউটিলিটির পাশাপাশি যাচাইযোগ্য স্বচ্ছতার অভূতপূর্ব লেভেল অফার করতে পারি। উপরের ডেটা শুধুমাত্র স্বচ্ছতা, শিক্ষামূলক এবং তথ্যগত উদ্দেশ্যে সংকলিত। DeHub এবং এর সব অ্যাফিলিয়েট আমাদের রিলিজ করা কোনো টোকেন বা NFT কিনে আর্থিক ক্ষতির জন্য কোনো দায়ভার বহন করবে না। মার্কেট অত্যন্ত অস্থির, বিশেষ করে আমাদের মতো নতুন মার্কেটগুলো। হ্যাক, অযোগ্যতা বা টেকনিক্যাল ত্রুটির কারণে আপনি আপনার সব টাকাও হারাতে পারেন। তাই, আপনার শুধু ততটুকুই খরচ করা উচিত যতটুকু হারানোর সামর্থ্য আপনার আছে।',
