    paragraph2: 'DeHub প্ল্যাটফর্মে DeHub টোকেনগুলির যেকোনো ব্যবহার প্রত্যাখ্যান করার অধিকার DeHub সংরক্ষণ করে। DeHub নিম্নলিখিত যেকোনো প্রত্যক্ষ বা পরোক্ষ ক্ষতি বা ক্ষতির জন্য কোনো দায়িত্ব প্রত্যাখ্যান করে: (i) প্রদত্ত কোনো তথ্যের উপর নির্ভরতা, (ii) কোনো ত্রুটি, বাদ পড়া বা তথ্যের মধ্যে ভুল; অথবা (iii) এই ধরনের তথ্যের ফলে কোনো পদক্ষেপ।',
