    contentRestrictionsText: 'কন্টেন্ট সীমাবদ্ধ, অপসারিত বা অনুপলব্ধ করা হতে পারে:',
    welcomeTitle: 'DeHub-এ স্বাগতম!',
    ourService: 'আমাদের সার্ভিস',
    ourServiceText1: 'এই সার্ভিসটি আপনাকে সম্পূর্ণ বিকেন্দ্রীভূত পরিবেশে কন্টেন্ট আবিষ্কার, শেয়ার এবং তা থেকে আয় করার সুযোগ দেয়। এটি সারা বিশ্বের মানুষের সাথে সংযোগ স্থাপন, তথ্য আদান-প্রদান এবং একে অপরকে অনুপ্রাণিত করার একটি ফোরাম হিসেবে কাজ করে। এছাড়া, কোনো কেন্দ্রীয় বিধিনিষেধ ছাড়াই মূল কন্টেন্ট নির্মাতাদের জন্য এটি একটি ডিস্ট্রিবিউশন প্ল্যাটফর্ম। আমরা এমন একটি সেন্সরশিপ-প্রতিরোধী প্ল্যাটফর্ম প্রদান করি যেখানে কর্পোরেট নিয়ন্ত্রণের পরিবর্তে কমিউনিটি গভর্নেন্সের মাধ্যমে যে কেউ তাদের কন্টেন্ট থেকে আয় করতে পারে।',
    ourServiceText2: 'DeHub একটি বিকেন্দ্রীভূত প্রোটোকল হিসেবে কাজ করে, যেখানে কন্টেন্ট মডারেশন কমিউনিটি গভর্নেন্সের মাধ্যমে পরিচালিত হয়। এটি নিশ্চিত করে যে শুধুমাত্র বেআইনি কন্টেন্ট বা কমিউনিটি-অনুমোদিত নির্দেশিকা লঙ্ঘনকারী কন্টেন্টগুলোই সীমাবদ্ধ করা হতে পারে।',
    softwareDevelopers: 'DeHub কারা পরিচালনা করে',
    softwareDevText1: 'DeHub একটি স্বাধীন DAO। কোনো কোম্পানি এই সার্ভিসটির মালিক নয়, এটি পরিচালনা বা নিয়ন্ত্রণ করে না। প্রোটোকল, প্ল্যাটফর্ম এবং ট্রেজারি অন-চেইন DeHub টোকেন হোল্ডারদের দ্বারা DeHub গভর্নেন্স প্রোটোকলের মাধ্যমে পরিচালিত হয়, যা বর্তমানে চালু আছে: অ্যাপের মধ্যে প্রস্তাব উত্থাপন এবং ভোট দেওয়া হয় এবং এর ফলাফল পুরো ইকোসিস্টেমের জন্য বাধ্যতামূলক। এই চুক্তিতে "DeHub", "আমরা", "আমাদের" বলতে DAO এবং এটি যে প্রোটোকল পরিচালনা করে তাকে বোঝায়, কোনো কোম্পানিকে নয়।',
    softwareDevText2: 'উন্নয়ন কাজগুলো DAO দ্বারা নিযুক্ত স্বাধীন কন্ট্রিবিউটর এবং স্টুডিওগুলো করে থাকে। তাদের কেউই DeHub ইকোসিস্টেমের মালিক নয় বা এর ওপর কোনো সিদ্ধান্ত নেওয়ার ক্ষমতা রাখে না এবং গভর্নেন্স ভোটের মাধ্যমে তাদের যেকোনো সময় সরিয়ে দেওয়া বা পরিবর্তন করা সম্ভব। এই প্রক্রিয়ার বাইরে কেউ প্রোটোকল, টোকেন বা এই শর্তাবলী পরিবর্তন করতে পারবে না।',
