    parentPermission: 'অভিভাবকের অনুমতি',
    parentPermissionText: 'আপনার বয়স ১৮ বছরের নিচে হলে, এই সার্ভিস ব্যবহারের জন্য আপনার বাবা-মা বা আইনি অভিভাবকের অনুমতি থাকতে হবে। অনুগ্রহ করে তাদের সাথে এই চুক্তিটি পড়ে নিন।',
