    walletConnections: 'ওয়ালেট কানেকশন এবং পরিচয়',
    walletText1: 'আপনি ওয়ালেট কানেক্ট না করেই সার্ভিসের কিছু অংশ ব্যবহার করতে পারবেন, যেমন কন্টেন্ট ব্রাউজ করা বা খুঁজে বের করা। তবে, মনিটাইজেশন ফিচার ব্যবহার করতে এবং গভর্নেন্সে অংশগ্রহণ করতে আপনার একটি সামঞ্জস্যপূর্ণ ক্রিপ্টো ওয়ালেট প্রয়োজন।',
