    q9: 'DeHub-এ বিজ্ঞাপন কিভাবে কাজ করে?',
    a9: 'আমাদের AI টুলকিটগুলি ডেভেলপার এবং ব্যবহারকারীদের DeHub ইকোসিস্টেমে সমন্বিত উন্নত AI-চালিত সরঞ্জাম এবং পরিষেবা সরবরাহ করে, যা d\'Apps এবং গেমগুলিতে কার্যকারিতা বৃদ্ধি করে।',
    q10: 'DeHub কোন কোন ব্লকচেইন নেটওয়ার্ক সাপোর্ট করে?',
    a10: 'DeHub একাধিক EVM-সামঞ্জস্যপূর্ণ চেইনে কাজ করে। নেটওয়ার্কের বিস্তারিত টোকেন ব্রিজ সেকশনে দেখো।',
    a3: 'প্রস্তাবগুলি গভর্নেন্স পেজ থেকে উত্থাপিত এবং ভোট দেওয়া হয়। একটি প্রস্তাব খোলার জন্য ১০,০০০ DeHub টোকেন ফি লাগে, যা চেইনে নিশ্চিত করা হয়, যা বোর্ডকে স্প্যাম মুক্ত রাখে। ভোট দেওয়া নিজেই বিনামূল্যে এবং আপনার স্টেকং ব্যাজ দ্বারা ওজনযুক্ত। একটি ভোট সাত দিন ধরে চলে, এবং একটি প্রস্তাব শুধুমাত্র তখনই ওজনযুক্ত সংখ্যাগরিষ্ঠতায় পাস হয় যদি কমপক্ষে দশটি ভিন্ন ওয়ালেট অংশ নেয়, তাই কোনও একক বড় হোল্ডার একা কিছু পাস করতে পারে না।',
    a7: 'DeHub এর ভিতরেই ছয়টি গেম চলে, একটি ব্রাউজার ট্যাবে, ইনস্টল করার কিছু নেই এবং কেনার কিছু নেই: কিং\'স গ্যাম্বিট (অনলাইন এলো ল্যাডার সহ ৩ডি দাবা), ক্লড অফ ডিউটি (একটি শুটার যা আপনার মেশিনে নিজের সমস্ত আর্ট তৈরি করে), জঙ্গল ট্রেইল (একটি পদ্ধতিগতভাবে তৈরি রেইনফরেস্ট ওয়াক), স্ট্রিট স্লেয়ার (DeHub এর জন্য নির্মিত একটি সাইড-স্ক্রলিং বিট \'এম আপ), চার্টোপিয়া (একটি হাঁটার যোগ্য ট্রেডিং ফ্লোর যা ভিআর হেডসেটেও চলে) এবং গডস আই (DeHub কমিউনিটির একটি লাইভ ৩ডি গ্লোব)। লাস্ট চ্যাড স্ট্যান্ডিং, আমাদের ফ্ল্যাগশিপ এমএমএ ব্যাটেল রয়্যাল, উন্নয়নাধীন।',
    a13: 'টোকেন হোল্ডাররা গভর্নেন্স পেজ থেকে অংশগ্রহণ করে: তাদের থ্রেডেড মন্তব্যে প্রস্তাবগুলি পড়ুন এবং আলোচনা করুন, বিনামূল্যে আপনার ব্যাজ দ্বারা নির্ধারিত ওজন দিয়ে পক্ষে বা বিপক্ষে ভোট দিন, অথবা ১০,০০০ টোকেন ফি দিয়ে আপনার নিজের একটি প্রস্তাব খুলুন। ডিএও ট্রেজারি পেজ যে কাউকে DeHub টোকেন জমা দিতে এবং সেই ট্রেজারি কীভাবে ব্যয় করা হবে সে সম্পর্কে ভোট দিতে দেয়, যা তারা যা জমা দিয়েছে তার অনুপাতে।',
    a22: 'না। আপনি Google, Apple বা Telegram দিয়ে সাইন ইন করতে পারেন, আপনার ইমেল ঠিকানায় বা SMS এর মাধ্যমে পাঠানো একটি কোড সহ, অথবা একটি পাসকি সহ, এবং আপনার জন্য ব্যাকগ্রাউন্ডে একটি নন-কাস্টোডিয়াল ওয়ালেট তৈরি করা হয় — আপনি কীগুলি ধরে রাখেন এবং আমরা কখনই কাস্টোডি নিই না। আপনার যদি ইতিমধ্যে একটি ওয়ালেট থাকে তবে আপনি এটি সংযোগ করতে বা এর কীগুলি আমদানি করতে পারেন। ওয়ালেট-ভিত্তিক নয় এমন সাইন-ইনগুলির গ্যাস ফিও স্পনসর করা হয়, তাই আপনি কোনও নেটিভ টোকেন না কিনে পোস্ট, টিপ এবং সংগ্রহ করতে পারেন।',
    a29: 'ক্রিয়েটররা এটি কম্পোজ করার সময় একটি পোস্টকে পরিপক্ক হিসাবে চিহ্নিত করে, এবং সেই পোস্টগুলি পাবলিক হোম ফিড থেকে এবং সার্চ থেকে দূরে থাকে যদি না আপনি সেটিংসে "Show mature content" চালু করেন। আপনি যেকোনো পোস্টের ⋯ মেনু থেকে একজন লেখককে মিউট বা ব্লক করতে পারেন, প্রতি ক্যাটাগরি অনুযায়ী কোন নোটিফিকেশন আপনার কাছে পৌঁছাবে তা বেছে নিতে পারেন এবং একটি পিন দ্বারা সুরক্ষিত কিডস মোড চালু করতে পারেন, যাতে একটি ডিভাইস শুধুমাত্র শিশুদের জন্য তৈরি পোস্টগুলি দেখায়।',
