    howItWorksDesc1: 'প্রত্যেকটা DeHub অ্যাকাউন্টের ভিতরে একটা ওয়ালেট আছে। আপনে আমাদের Stripe গেটওয়ে দিয়া কার্ডের মাধ্যমে এটার মইধ্যে টাকা ভরতে পারবা, অন্য ইউজারের কাছ থিকা পাইতে পারবা, প্ল্যাটফর্ম থিকা ইনকাম করতে পারবা, অথবা যেকোনো সেলফ-কাস্টোডিয়াল ওয়ালেট থিকা ডিপোজিট করতে পারবা—শুরু করার লাগি আলাদা কোনো অ্যাপ, এক্সটেনশন বা সিড ফ্রেজের দরকার নাই। ব্যালেন্স, টিপস, আনলক আর রিওয়ার্ড সব DeHub টোকেনে সেটেল অয়, তাই ভ্যালু সরাসরি ইউজারদের মইধ্যে আদান-প্রদান অয়, কোনো পেমেন্ট প্রসেসরের মাধ্যমে না যে কমিশন কাইটা নেয় আর অ্যাকাউন্ট ফ্রিজ করতে পারে।',
    howItWorksDesc2: 'হোল্ডিং আর স্টেকিংও অ্যাপটা আপনের লাগি কেমনে কাজ করব তা বদলাইয়া দেয়। আপনে যত বেশি DeHub টোকেন হোল্ড করবা, আপনের প্ল্যাটফর্ম ফি তত কম অইব আর তত বেশি সুবিধা আনলক অইব—ব্যাজ, ভেরিফিকেশন, ট্রেন্ড বুস্ট, ক্লাব টিয়ার আর নেটওয়ার্ক জুড়ে বাড়তি অধিকার। বাস্তবে এই কারেন্সি কোনো বাড়তি জিনিস না: এটা অইলো পারমিশন লেয়ার, রিওয়ার্ড রেল আর চেকআউট, সব এক লগে।',
