    step1Title: 'আপনার অ্যাকাউন্ট তৈরি করুন',
    step1Desc: 'dehub.io ওপেন করুন আর সাইন ইন-এ ট্যাপ করুন। গুগল, অ্যাপল, টেলিগ্রাম, ইমেইল, এসএমএস, পাসকি (passkey) অথবা ওয়ালেট বাছুন। ব্যাকগ্রাউন্ডে আপনার লাগি একটা নন-কাস্টোডিয়াল ওয়ালেট তৈরি হইবো — চাবি আপনার কাছেই থাকবো — আর গ্যাস ফি স্পনসর করা, তাই শুরু করার আগে কোনো টাকা জমানোর দরকার নাই।',
    step2Title: 'আপনার প্রোফাইল সেটআপ করুন',
    step2Desc: 'সেটিংস → প্রোফাইল-এ গিয়া একটা ডিসপ্লে নেম, ইউজারনেম, অবতার, কভার ইমেজ আর বায়ো যোগ করুন, আর আপনার অন্য সোশ্যাল মিডিয়া লিংক করুন যাতে আপনার প্রোফাইলে আপনার টোটাল রিচ দেখা যায়। ওইখানে থাকা অবস্থায় সেটিংস → অ্যাপিয়ারেন্স-এ গিয়া একটা থিম বাছুন, আর যদি আপনি সব কিছু ঘুরিয়া দেখতে চান তবে ঐচ্ছিক গাইডেড ওয়াকথ্রু (walkthrough) নিতে পারেন।',
    step3Title: 'আপনার প্রথম পোস্ট করুন',
    step3Desc: 'ক্রিয়েট (Create)-এ ট্যাপ করুন। একটা পোস্ট লেখুন, ছবি, ভিডিও বা অডিও যোগ করুন, বড় লেখালেখির লাগি আর্টিকেল মোডে সুইচ করুন, অথবা লাইভে যান। প্রতিদিনের একটা নির্দিষ্ট লিমিট পর্যন্ত পোস্ট করা ফ্রি — ব্যাজ ছাড়া প্রতিদিন দশটা টেক্সট পোস্ট আর এক গিগাবাইট মিডিয়া। অন-চেইন পোস্ট মিন্ট করা ঐচ্ছিক আর এটা পরেও করা যাইবো।',
    step4Desc: 'প্রতিটা পোস্টে ডিহাব (DeHub) টোকেন দিয়া টিপ দেওয়া যাইবো। এরপরে আপনি সাবস্ক্রিপশন বিক্রি করতে পারবেন, পে-পার-ভিউ পোস্ট পাবলিশ করতে পারবেন, ডাইরেক্ট মেসেজের লাগি মিনিমাম টিপ সেট করতে পারবেন, দোকান খুলতে পারবেন, বাউন্টি পোস্ট করতে পারবেন আর আপনার অ্যাফিলিয়েট লিংক শেয়ার কইরা নতুন মানুষ আইনা ইনকাম করতে পারবেন।',
    step5Title: 'ব্যাজের লাগি টোকেন হোল্ড করুন',
    step5Desc: 'ডিহাব (DeHub) টোকেন হোল্ড বা স্টেক করলে একটা ব্যাজ পাওয়া যায়, ক্র্যাব (Crab) থাইকা মেগালোডন (Megalodon) পর্যন্ত। ব্যাজ থাকলে আপনার ফি কমবো, পোস্ট করার লিমিট বাড়বো, সুপারপাওয়ার আনলক হইবো আর আপনার ভিউ, রিঅ্যাকশন আর ভোটের ওজন বাড়বো।',
    step6Title: 'আপনার ওয়ালেট ব্যবহার করুন',
    step6Desc: 'আপনার ওয়ালেটে ডিহাব (DeHub) টোকেন আর বিভিন্ন চেইনের অন্য ক্রিপ্টো থাকে। কার্ড দিয়া বা ক্রিপ্টো দিয়া $০.৫০ থাইকা টোকেন কিনুন, যে কাউরে ফ্রিতে পাঠান, ডিহাব এক্সচেঞ্জে ট্রেড করুন, আর ব্যাজ লেভেলে উপরে উঠার লাগি স্টেক করুন।',
